  ('ng-ax19-blue-hawk', 'Main Body', 200, 'Reduced to zero, the armor shuts down completely and the pilot is open to attack.', 14);

INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('ng-x30-aurora-blazer', 1, 'NG-X530 Blazer Over-and-Under Assault Rifle (1, handheld)', 'Laser: 2D6 M.D. single shot or 4D6+5 M.D. triple pulse. Plasma: 2D6+3 M.D. single shot, 4D6+6 M.D. for two simultaneous blasts, 6D6+10 for three, 1D4x10+14 M.D. for four', 1, 'Laser 2,000 ft (610 m); plasma 800 ft (244 m)', 'Each single shot, laser pulse or multiple plasma blast counts as one melee attack; laser and plasma cannot fire together', 'Effectively unlimited on the UEL. Otherwise each barrel has its own E-Clip: 10 triple-pulse laser blasts or 6 quadruple plasma blasts per standard E-Clip, double for a long E-Clip', NULL, 'Anti-monster and anti-armor (plasma), anti-personnel and precision shooting (laser). An experimental precision laser over a four-barrel plasma gun, sold only with the Aurora Blazer and (optionally) the Lynx; carries a removable shoulder strap. No separate price printed.'),
  ('ng-x30-aurora-blazer', 2, 'Thruster Mounted Mini-Missile Launchers (2)', 'Varies by mini-missile: fragmentation 5D6 M.D., armor piercing 1D4x10 M.D., plasma 1D6x10 M.D.; smoke and tear gas possible', 1, 'One mile (1.6 km)', 'One at a time or volleys of 2 or 4', '8 total; four per launcher, one launcher on top of each thruster behind the shoulders', NULL, 'Assault and anti-armor, secondarily defense and anti-missile. Mini-torpedoes may be loaded instead for marine operations.'),
  ('ng-nx12-beach-stormer', 1, 'NG-P67 Particle Beam Short-Gun', '6D6 M.D. per shot', 1, '1,000 ft (305 m) in air; 700 ft (213 m) underwater', 'Each blast counts as one melee attack', '10 per standard E-Clip, or drawn from the suit''s battery by a forearm cable at one hour of operating time per 30 shots (not a factor for nuclear suits)', NULL, 'Assault, secondarily anti-personnel. A water-capable cut-down of NG''s P7 particle beam rifle, shorter but heavy and awkward: -2 to strike for a human P.S. under 26. Weight 16 lbs (7.2 kg). Sold separately for 25,600 credits (gear row ng-p67-particle-beam-short-gun). The book adds that an ordinary particle beam weapon has half range and half damage underwater.'),
  ('ng-nx12-beach-stormer', 2, 'NG-M100 Multi-Weapon Underwater Rifle', 'Ion blaster 4D6 M.D.; grenades 4D6 M.D. each; micro-torpedoes 5D6 M.D. each (grenades and torpedoes armor piercing, 3 ft/0.9 m blast radius)', 1, 'Ion blaster 800 ft (244 m); grenades or micro-torpedoes 1,400 ft (427 m)', 'Each blast counts as one melee attack/action', 'Ion blaster 10 shots per standard E-Clip; 20 grenades or micro-torpedoes per magazine', NULL, 'Anti-sea monster and anti-ship, secondarily defense. A handheld over-under rifle exclusive to the Beach-Stormer: an ion blaster that fires in or out of water over a launcher based on Wellington''s WI-23 that takes grenade or micro-torpedo box magazines, fired cold by compressed air. Weight 20 lbs (9 kg); each magazine 12 lbs (5.4 kg). Sold separately for 34,000 credits (gear row ng-m100-multi-weapon-underwater-rifle).'),
  ('ng-x44-blue-boy', 1, 'NG-X144 "Thumper" Dual Assault Rifle', 'Laser 2D6 M.D. per shot (or a no-damage targeting setting). Grenades, one/volley of three: fragmentation 3D6 M.D. to a 12 ft (3.7 m) radius / 1D4x10+3 M.D.; high explosive/armor piercing 4D6 M.D. to 3 ft (0.9 m) / 1D6x10+6 M.D.; plasma 6D6 M.D. to 5 ft (1.5 m) / 2D4x10+12 M.D.', 1, 'Laser 1,600 ft (488 m); grenade launcher 1,200 ft (366 m)', 'Laser single shot, each one melee attack. Grenades one at a time or a rapid volley of two or three, all of one type, at one target (burst) or split between targets (Shooting Wild)', 'Laser effectively unlimited from the suit''s power supply; it cannot work off the armor. Grenades: 9 in the weapon, 3 more stowed on the gun, and 42 in the hard-shell backpack (36 combat grenades of explosive, plasma or Hex, and 6 smoke or other special); hand reloading costs one melee round for a trained soldier, 1D4 rounds otherwise', '+1 to strike with the laser on an Aimed/Called Shot; +1 to strike with a single grenade on an Aimed/Called Shot', 'Assault, secondarily defense. A grenade launcher over a precision laser on a Glitter Boy style swivel mount behind the shoulder, exclusive to the Blue Boy; it swings forward to fire through 180 degrees side to side and up and down, and can be locked for steadier aimed shots. Special grenades: smoke covers 40 ft (12.2 m); tear gas 25 ft (7.6 m), unprotected victims -10 to strike, parry and dodge, -3 initiative and one attack lost while in it and 1D6+1 rounds after; stun/flash 4 ft (1.2 m), -10 to strike, parry and dodge, -1 initiative and one attack lost for 1D4 rounds; a volley of three triples the radius of smoke, tear gas or flash.'),
  ('ng-x44-blue-boy', 2, 'Forearm Volt Disruptor', '1D4 S.D.C. from the darts, plus an electric charge: on S.D.C. people the effect of a Neural Mace (Rifts Ultimate Edition); on S.D.C. electronics roll percentile: 01-10 destroyed, 11-66 1D4 components burnt out, 67-80 down 1D4 melee rounds then at 60%, 81-90 out 2D4 minutes then half capacity 2D4 minutes, 91-00 down 1D4 melee rounds then fine', 0, '15 ft (4.6 m)', 'All three darts fire per attack, one melee attack; a further full melee round to reel them in', 'Reusable: respooled and recharged in two melee rounds; two spare sets of darts and wires', NULL, 'Anti-communications and electronics, secondarily sabotage and stunning personnel. A left-forearm taser-style launcher of three wired darts. Useless against environmental armor, cyborgs, power armor, vehicles and other M.D.C. targets; double damage to supernatural creatures vulnerable to electricity.'),
  ('ng-ax19-blue-hawk', 1, 'Ion Rifle', '5D6 M.D.', 1, '2,000 ft (610 m)', 'Single blasts, each one melee attack', 'Effectively unlimited on the UEL from a nuclear or Solid Oxide suit; 40 shots per charge on electric battery versions; 8 per standard E-Clip, 16 per long E-Clip', NULL, 'Anti-ship and anti-sea monster, secondarily anti-submarine. A large handheld ion rifle that works as well underwater as in air. Shooting from the air at a submerged target is -2 to strike; surface targets carry no penalty. No separate price printed.'),
  ('ng-ax19-blue-hawk', 2, 'Mini-Torpedoes (8)', '2D4x10 M.D. high explosive or 1D6x10 M.D. plasma', 1, '5 miles (8 km)', 'One at a time', '8; four per wing', NULL, 'Anti-ship and anti-sea monster, secondarily anti-submarine. Light self-guiding torpedoes launched in flight or submerged; swapped for mini-missiles away from open water.'),
  ('ng-ax19-blue-hawk', 3, 'Scythe-Forearm Vibro-Blades (2)', '2D4 M.D. per strike at 60 mph (96 km) or less; 4D4 M.D. at 61-150 mph (97.6-240 km); 6D4 M.D. faster than that; dive attack 4D4+4 M.D. (two melee attacks)', 1, 'Close combat', 'Per hand to hand attack', NULL, NULL, 'Anti-sea monster, secondarily defense. Retractable, one in each forearm.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 4 machines are in' AS assertion, count(*) AS got, 4 AS want
  FROM vehicles WHERE slug IN ('ng-x30-aurora-blazer', 'ng-nx12-beach-stormer', 'ng-x44-blue-boy', 'ng-ax19-blue-hawk');
SELECT 'their 41 locations are in' AS assertion, count(*) AS got, 41 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('ng-x30-aurora-blazer', 'ng-nx12-beach-stormer', 'ng-x44-blue-boy', 'ng-ax19-blue-hawk');
SELECT 'their 9 weapon entries are in' AS assertion, count(*) AS got, 9 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('ng-x30-aurora-blazer', 'ng-nx12-beach-stormer', 'ng-x44-blue-boy', 'ng-ax19-blue-hawk');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('ng-x30-aurora-blazer', 'ng-nx12-beach-stormer', 'ng-x44-blue-boy', 'ng-ax19-blue-hawk') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~299-northern-gun-2-power-armor-a.sql');
